class Task:
    def __init__(self, id, C, D, T):
        self.id = id
        self.C = C  # Worst-Case Execution Time
        self.D = D  # Relative Deadline
        self.T = T  # Minimum Inter-arrival Time (Period)
        self.U = C / T # Utilization
        self.R = None # Worst-Case Response Time (to be computed)

def check_constrained_deadlines(task_set):
    for task in task_set:
        if task.D > task.T:
            return False
    return True

def get_priority_sets(task_k, task_set, priority_order):
    hp_k = set()
    lp_k = set()
    hep_k = set()
    lep_k = set()
    k_priority = priority_order[task_k.id]

    for task in task_set:
        if task.id == task_k.id:
            hep_k.add(task)
            lep_k.add(task)
        else:
            task_priority = priority_order[task.id]
            if task_priority < k_priority:
                hp_k.add(task)
                hep_k.add(task)
            else:
                lp_k.add(task)
                lep_k.add(task)
    return hp_k, lp_k, hep_k, lep_k

