def calculate_N_i_L(C_i, T_i, L):
    return math.floor((L - C_i) / T_i) + 1

def calculate_W_D_i_L(C_i, T_i, L):
    N_i_L = calculate_N_i_L(C_i, T_i, L)
    return N_i_L * C_i + min(C_i, L - C_i - (N_i_L - 1) * T_i)

def calculate_I_D_i_D_k(C_i, T_i, D_k, C_k):
    W_D_i_D_k = calculate_W_D_i_L(C_i, T_i, D_k)
    return min(W_D_i_D_k, D_k - C_k + 1)

def da_test_is_schedulable(task_k, task_set, priority_order, m):
    hp_k = get_hp_tasks(task_k, task_set, priority_order)

    total_interference = 0
    for task_i in hp_k:
        total_interference += calculate_I_D_i_D_k(task_i.C, task_i.T, task_k.D, task_k.C)

    return task_k.C + total_interference <= m * task_k.D

def calculate_N_R_i_L(C_i, T_i, L, UB_R_i):
    return math.floor((L - UB_R_i) / T_i) + 1

def calculate_W_R_i_L(C_i, T_i, L, UB_R_i):
    N_R_i_L = calculate_N_R_i_L(C_i, T_i, L, UB_R_i)
    return N_R_i_L * C_i + min(C_i, L - UB_R_i - (N_R_i_L - 1) * T_i)

def calculate_I_R_i_UB_R_k(C_i, T_i, UB_R_i, UB_R_k, C_k):
    W_R_i_UB_R_k = calculate_W_R_i_L(C_i, T_i, UB_R_k, UB_R_i)
    return min(W_R_i_UB_R_k, UB_R_k - C_k + 1)

def rta_test_compute_ub_r_k(task_k, task_set, priority_order, m, max_iterations=100):
    hp_k = get_hp_tasks(task_k, task_set, priority_order)

    current_ub_r_k = task_k.C
    for _ in range(max_iterations):
        total_interference = 0
        for task_i in hp_k:
            # Assume UB_R_i for higher priority tasks are already converged
            # This requires computing tasks in priority order
            if task_i.R is None:
                # This indicates a dependency issue or an unschedulable higher priority task
                return float('inf') # Or handle error
            total_interference += calculate_I_R_i_UB_R_k(task_i.C, task_i.T, task_i.R, current_ub_r_k, task_k.C)

        next_ub_r_k = task_k.C + math.ceil(total_interference / m)

        if next_ub_r_k == current_ub_r_k:
            return next_ub_r_k
        if next_ub_r_k > task_k.D:
            return float('inf') # Unschedulable
        current_ub_r_k = next_ub_r_k
    return float('inf') # Did not converge within max_iterations

def rta_test_is_schedulable(task_k, task_set, priority_order, m):
    ub_r_k = rta_test_compute_ub_r_k(task_k, task_set, priority_order, m)
    return ub_r_k <= task_k.D

def aj_test_compute_ub_r_k(task_k, task_set, priority_order, m, max_iterations=100):
    hp_k = get_hp_tasks(task_k, task_set, priority_order)

    current_ub_r_k = task_k.C
    for _ in range(max_iterations):
        total_interference_workload = 0
        for task_i in hp_k:
            # Workload of task_i in an interval of length current_ub_r_k
            workload_i = (math.ceil(current_ub_r_k / task_i.T) * task_i.C) + task_i.C
            total_interference_workload += workload_i

        next_ub_r_k = task_k.C + math.ceil(total_interference_workload / m)

        if next_ub_r_k == current_ub_r_k:
            return next_ub_r_k
        if next_ub_r_k > task_k.D:
            return float('inf') # Unschedulable
        current_ub_r_k = next_ub_r_k
    return float('inf') # Did not converge

def aj_test_is_schedulable(task_k, task_set, priority_order, m):
    ub_r_k = aj_test_compute_ub_r_k(task_k, task_set, priority_order, m)
    return ub_r_k <= task_k.D

def audsleys_opa_algorithm(task_set, S, m):
    n = len(task_set)
    assigned_priorities = [None] * n # priority_order[0] is highest, priority_order[n-1] is lowest
    unassigned_tasks = set(task_set)

    # Assign priorities from lowest (n-1) to highest (0)
    for current_priority_level in range(n - 1, -1, -1):
        found_schedulable_task = None
        for task_candidate in unassigned_tasks:
            # Temporarily assign task_candidate to current_priority_level
            # and check its schedulability with S
            # This check needs to consider the already assigned lower priority tasks
            # and the set of unassigned tasks as higher priority tasks.

            # (Simplified check for sketch: S.check_schedulability(task_candidate, current_priority_level, ...))
            # The actual check is more complex, involving the 'set' of higher/lower tasks.

            # For OPA, when checking task_candidate at current_priority_level:
            #   hp_set = unassigned_tasks - {task_candidate}
            #   lp_set = {task for task in task_set if task not in unassigned_tasks and task != task_candidate}
            #   If S.is_schedulable(task_candidate, hp_set, lp_set, current_priority_level, m):
            #       found_schedulable_task = task_candidate
            #       break

            # A more direct way to model the check within OPA:
            # Construct a temporary priority assignment for the check:
            temp_priority_order = {}
            for t in unassigned_tasks:
                if t == task_candidate:
                    temp_priority_order[t.id] = current_priority_level
                else:
                    # Assign other unassigned tasks to higher priorities (arbitrary order within hp_set)
                    temp_priority_order[t.id] = current_priority_level - 1 # Placeholder for higher
            for p_idx, t_assigned in enumerate(assigned_priorities):
                if t_assigned is not None:
                    temp_priority_order[t_assigned.id] = p_idx

            # Check if task_candidate is schedulable at current_priority_level
            # This requires S to be able to check a single task's schedulability given a partial assignment
            if S.is_task_schedulable(task_candidate, temp_priority_order, task_set, m):
                found_schedulable_task = task_candidate
                break

        if found_schedulable_task is None:
            return None # No schedulable ordering found by S

        assigned_priorities[current_priority_level] = found_schedulable_task
        unassigned_tasks.remove(found_schedulable_task)

    return assigned_priorities # Returns a priority ordering (list of tasks by priority level)
